// WF-02: deterministic keyword detection first (no AI). Builds sql/params + an AI prompt for the fallback.
function buildSql(action, email, description, category){
  let sql='SELECT 1 AS ok', params=[];
  switch(action){
    case 'CLOCK_IN': sql=`WITH u AS (SELECT user_id FROM users WHERE email=$1)\nINSERT INTO attendance (user_id, work_date, clock_in)\nSELECT u.user_id, CURRENT_DATE, now() FROM u\nON CONFLICT (user_id, work_date) DO UPDATE SET clock_in = COALESCE(attendance.clock_in, now())\nRETURNING to_char(clock_in,'HH24:MI') AS clock_in, work_date`; params=[email]; break;
    case 'CLOCK_OUT': sql=`WITH u AS (SELECT user_id FROM users WHERE email=$1)\nUPDATE attendance a SET clock_out = now(), total_minutes = ROUND(EXTRACT(EPOCH FROM (now() - a.clock_in))/60)\nFROM u WHERE a.user_id=u.user_id AND a.work_date=CURRENT_DATE AND a.clock_in IS NOT NULL\nRETURNING to_char(a.clock_out,'HH24:MI') AS clock_out, a.total_minutes`; params=[email]; break;
    case 'ADD_WORK_ENTRY': sql=`WITH u AS (SELECT user_id FROM users WHERE email=$1)\nINSERT INTO daily_work_entries (user_id, work_date, description, category)\nSELECT u.user_id, CURRENT_DATE, $2, $3 FROM u\nRETURNING description, category, work_date`; params=[email, description, category]; break;
    case 'GET_TODAY': sql=`WITH u AS (SELECT user_id FROM users WHERE email=$1)\nSELECT (SELECT to_char(clock_in,'HH24:MI') FROM attendance a WHERE a.user_id=u.user_id AND work_date=CURRENT_DATE) AS clock_in,\n (SELECT to_char(clock_out,'HH24:MI') FROM attendance a WHERE a.user_id=u.user_id AND work_date=CURRENT_DATE) AS clock_out,\n (SELECT string_agg(description, '; ') FROM daily_work_entries d WHERE d.user_id=u.user_id AND work_date=CURRENT_DATE) AS work\nFROM u`; params=[email]; break;
    case 'GET_WEEK': sql=`WITH u AS (SELECT user_id FROM users WHERE email=$1)\nSELECT COALESCE(json_agg(row_to_json(x)),'[]') AS days FROM (\n SELECT to_char(work_date,'Dy DD Mon') AS day, to_char(clock_in,'HH24:MI') AS clock_in, to_char(clock_out,'HH24:MI') AS clock_out, total_minutes\n FROM attendance a JOIN u ON a.user_id=u.user_id\n WHERE date_trunc('week',work_date)=date_trunc('week',CURRENT_DATE) ORDER BY work_date) x`; params=[email]; break;
    case 'SUBMIT_WEEK': sql=`WITH u AS (SELECT user_id FROM users WHERE email=$1)\nINSERT INTO weekly_reports (user_id, iso_year, iso_week, status, submitted_at)\nSELECT u.user_id, EXTRACT(ISOYEAR FROM CURRENT_DATE)::int, EXTRACT(WEEK FROM CURRENT_DATE)::int, 'SUBMITTED', now() FROM u\nON CONFLICT (user_id, iso_year, iso_week) DO UPDATE SET status='SUBMITTED', submitted_at=now(), version = weekly_reports.version + 1\nRETURNING iso_week, status`; params=[email]; break;
    case 'REPORT_SICK': sql=`WITH u AS (SELECT user_id FROM users WHERE email=$1)\nINSERT INTO leave_requests (user_id, leave_type, start_date, end_date, reason, status)\nSELECT u.user_id, 'SICK', CURRENT_DATE, CURRENT_DATE, $2, 'SUBMITTED' FROM u\nRETURNING leave_type, to_char(start_date,'YYYY-MM-DD') AS start_date, status`; params=[email, description]; break;
    case 'NO_EMAIL': sql=`SELECT 'NO_EMAIL' AS err`; params=[]; break;
    default: sql=`SELECT 'UNKNOWN' AS err`; params=[];
  }
  return { sql, params };
}

const b = $json.body || $json;
const email = String(b.email || '').toLowerCase().trim();
let action = String(b.action || '').toUpperCase().trim();
const msgRaw = String(b.message || '').trim();
const msg = msgRaw.toLowerCase();
let description = b.description || '';
let category = b.category || 'General';

// Deterministic layer. Submit/Sick are checked BEFORE the view intents so phrases
// like 'hand in my week' or 'not well today' are not swallowed by 'week'/'today'.
if (!action && msg) {
  if (/clock\s*me?\s*in|check\s*in|punch\s*(me\s*)?in|sign\s*(me\s*)?in/.test(msg)) action = 'CLOCK_IN';
  else if (/clock\s*me?\s*out|check\s*out|punch\s*(me\s*)?out|sign\s*(me\s*)?out|knock\s*off|done for the day/.test(msg)) action = 'CLOCK_OUT';
  else if (/submit.*(report|week)|submit my|hand\s*in.*(report|week)|send.*(report|week)|turn\s*in.*(report|week)|hand in my (week|report)/.test(msg)) action = 'SUBMIT_WEEK';
  else if (/(i am|i'm|im)\s+sick|report sick|sick today|not\s*(feeling\s*)?well|unwell|staying\s*home|off\s*sick/.test(msg)) action = 'REPORT_SICK';
  else if (/what.*hours|show.*week|my week|this week/.test(msg)) action = 'GET_WEEK';
  else if (/show.*today|my day|what.*today|how.*today|today so far/.test(msg)) action = 'GET_TODAY';
  else if (/worked on|i worked|today i|i did|completed/.test(msg)) action = 'ADD_WORK_ENTRY';
  else action = 'UNKNOWN';
}
if (action === 'ADD_WORK_ENTRY' && !description) description = msgRaw.replace(/^(today\s+)?(i\s+)?(worked on|did|worked|completed)\s*/i, '').trim() || msgRaw;
if (action === 'REPORT_SICK' && !description) description = msgRaw || 'Reported sick via chatbot';
if (!email) action = 'NO_EMAIL';

const built = buildSql(action, email, description, category);

const aiPrompt = `You are the WIP workplace assistant. Classify the message into exactly one intent and extract fields. Respond ONLY with compact JSON with fields in THIS order: {"reason":"one short sentence deciding the intent","intent":"...","description":"...","category":"..."}. Think in 'reason' first, then commit to 'intent'. intent must be one of CLOCK_IN, CLOCK_OUT, ADD_WORK_ENTRY, GET_TODAY, GET_WEEK, SUBMIT_WEEK, REPORT_SICK, UNKNOWN. Decide by INTENT, not by keywords. GET_TODAY/GET_WEEK are ONLY for questions asking to VIEW data. Submitting/sending/handing in a report or week => SUBMIT_WEEK. Being sick/unwell/staying home => REPORT_SICK. For ADD_WORK_ENTRY, description = a concise summary of the work done (max 12 words, no preamble). Message: "${msgRaw}"`;
const geminiBody = { contents: [{ parts: [{ text: aiPrompt }] }], generationConfig: { responseMimeType: 'application/json', temperature: 0 } };

return [{ json: { action, email, description, category, message: msgRaw, sql: built.sql, params: built.params, aiPrompt, geminiBody } }];

