const dc = $('Detect Command').first().json;
const email = dc.email;
const msg = String(dc.message || '').toLowerCase();
let action='UNKNOWN', description='', category='General';
try {
  const parts = $json && $json.candidates && $json.candidates[0] && $json.candidates[0].content && $json.candidates[0].content.parts;
  const text = parts && parts[0] && parts[0].text;
  if (text) { const o = JSON.parse(text); action = String(o.intent||'UNKNOWN').toUpperCase(); description = o.description || dc.message; category = o.category || 'General'; }
} catch (e) { action = 'UNKNOWN'; }
const allowed = ['CLOCK_IN','CLOCK_OUT','ADD_WORK_ENTRY','GET_TODAY','GET_WEEK','SUBMIT_WEEK','REPORT_SICK'];
if (!allowed.includes(action)) action = 'UNKNOWN';
// Deterministic guards: the model over-anchors on 'week'/'today'. Correct obvious cues.
if (action === 'GET_WEEK' && /(submit|hand\s*in|send|turn\s*in|hand\s*over)/.test(msg)) action = 'SUBMIT_WEEK';
if (action === 'GET_TODAY' && /(sick|unwell|not\s*(feeling\s*)?well|staying\s*home|off\s*sick|feeling\s*ill)/.test(msg)) action = 'REPORT_SICK';
if (action === 'REPORT_SICK' && !description) description = dc.message || 'Reported sick via chatbot';
const built = buildSql(action, email, description, category);
return [{ json: { action, email, description, category, sql: built.sql, params: built.params, ai: true } }];

const src = $('Route to Action').first().json;
const action = src.action;
const email = src.email;
const ai = src.ai ? ' (AI)' : '';
const d = $json || {};
let reply = '';
switch (action) {
  case 'CLOCK_IN': reply = d.clock_in ? `\u2705 Clocked in at ${d.clock_in}.${ai}` : `\u26a0\ufe0f Could not clock you in (user not found: ${email}).`; break;
  case 'CLOCK_OUT': { const m = Number(d.total_minutes || 0); reply = d.clock_out ? `\ud83d\udc4b Clocked out at ${d.clock_out}. Total today: ${Math.floor(m/60)}h ${m%60}m.${ai}` : `\u26a0\ufe0f No open clock-in found for today.`; break; }
  case 'ADD_WORK_ENTRY': reply = d.description ? `\ud83d\udcdd Saved work entry: "${d.description}" (${d.category||'General'}).${ai}` : `\u26a0\ufe0f Could not save work entry.`; break;
  case 'GET_TODAY': reply = `\ud83d\udcc5 Today \u2014 In: ${d.clock_in||'\u2014'}, Out: ${d.clock_out||'\u2014'}\nWork: ${d.work||'(none logged)'}`; break;
  case 'GET_WEEK': { const days = d.days || []; reply = `\ud83d\uddd3\ufe0f This week:\n` + (days.length ? days.map(x => `\u2022 ${x.day}: ${x.clock_in||'\u2014'}\u2013${x.clock_out||'\u2014'}`).join('\n') : '(no attendance yet)'); break; }
  case 'SUBMIT_WEEK': reply = d.status ? `\ud83d\udce4 Week ${d.iso_week} report submitted to your mentor.${ai}` : `\u26a0\ufe0f Could not submit.`; break;
  case 'REPORT_SICK': reply = d.status ? `\ud83e\udd12 Sick leave logged for ${d.start_date}. Your mentor has been notified.${ai}` : `\u26a0\ufe0f Could not log sick leave.`; break;
  case 'NO_EMAIL': reply = `\u26a0\ufe0f No email supplied \u2014 cannot identify the user.`; break;
  default: reply = `\ud83e\udd14 I didn't understand that. Try: "clock me in", "I worked on ...", "submit my report", or "show my week".`;
}
return [{ json: { reply, action, email } }];
